package in.kalaimarket;
import org.junit.jupiter.api.Test;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.test.web.servlet.MockMvc;import org.springframework.mock.web.MockHttpSession;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.junit.jupiter.api.Assertions.*;
@WebMvcTest(controllers={SessionController.class,MarketController.class},properties={"app.admin.username=kalai","app.admin.password=1234567890","MT5_FEED_PASSWORD=1234567"}) @Import(SecurityConfig.class)
class SessionPersistenceTest {
 @Autowired MockMvc mvc;@MockitoBean TradeRepository plans;@MockitoBean WatchRepository watch;
 MockHttpSession signedIn() throws Exception {var anonymous=mvc.perform(get("/api/session")).andExpect(jsonPath("$.authenticated").value(false)).andReturn();var session=(MockHttpSession)anonymous.getRequest().getSession(false);return (MockHttpSession)mvc.perform(post("/api/session").session(session).with(httpBasic("kalai","1234567890"))).andExpect(status().isOk()).andReturn().getRequest().getSession(false);}
 @Test void reloadAuthenticatesUsingSessionWithoutPassword() throws Exception {var session=signedIn();mvc.perform(get("/api/me").session(session)).andExpect(status().isOk());mvc.perform(get("/api/session").session(session)).andExpect(jsonPath("$.authenticated").value(true)).andExpect(jsonPath("$.csrfToken").isString());}
 @Test void cookieWritesRequireCsrfAndLogoutInvalidatesSession() throws Exception {var session=signedIn();mvc.perform(delete("/api/session").session(session)).andExpect(status().isForbidden());mvc.perform(delete("/api/session").session(session).header("Authorization","Bearer ignored")).andExpect(status().isForbidden());mvc.perform(delete("/api/session").session(session).with(csrf())).andExpect(status().isOk());assertTrue(session.isInvalid());mvc.perform(get("/api/me")).andExpect(status().isUnauthorized());}
 @Test void feedCannotCreateBrowserAdminSession() throws Exception {mvc.perform(post("/api/session").with(httpBasic("mt5_feed","1234567"))).andExpect(status().isForbidden());}
}
